def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    change = new - old

    return {
        "value": change,
        "trace": {
            "old": old,
            "new": new,
            "change": change,
            "output_meta": {
                "currency": None,
                "scale": "thousand",
                "unit": None
            }
        }
    }
